fn sum(a: &Vec<u32>, b: &Vec<u32>) -> Vec<u32> {
    assert_eq!(
        a.len(),
        b.len(),
        "Input arrays must have the same length"
    );

    let mut c = Vec::with_capacity(a.len());
    for i in 0..a.len() {
        // We rely on the problem guarantee that a[i] + b[i] < 1000,
        // so this addition cannot overflow a u32.
        c.push(a[i] + b[i]);
    }
    c
}

